cat > BinlogReader.cs << 'CSEOF'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors and warnings
var errors = new List<(string file, int line, int col, string code, string message, string project)>();
var warnings = new List<(string file, int line, int col, string code, string message, string project)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((e.File ?? "", e.LineNumber, e.ColumnNumber, e.Code ?? "", e.Text ?? "", proj));
});

build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    warnings.Add((w.File ?? "", w.LineNumber, w.ColumnNumber, w.Code ?? "", w.Text ?? "", proj));
});

Console.WriteLine($"=== ERRORS ({errors.Count}) ===");
foreach (var e in errors)
    Console.WriteLine($"[{e.project}] {e.file}({e.line},{e.col}): error {e.code}: {e.message}");

Console.WriteLine();
Console.WriteLine($"=== WARNINGS ({warnings.Count}) ===");
foreach (var w in warnings)
    Console.WriteLine($"[{w.project}] {w.file}({w.line},{w.col}): warning {w.code}: {w.message}");

// Show project dependency info
Console.WriteLine();
Console.WriteLine("=== PROJECT REFERENCES ===");
build.VisitAllChildren<Project>(p => {
    var refs = new List<string>();
    p.VisitAllChildren<Item>(i => {
        if (i.Name == "ProjectReference")
            refs.Add(i.Text);
    });
    if (refs.Count > 0)
        Console.WriteLine($"{p.Name} -> {string.Join(", ", refs)}");
});
