using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

// Show all projects and their statuses
Console.WriteLine("=== PROJECTS ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}");

    // Show project references
    p.VisitAllChildren<Item>(i => {
        if (i.Name == "ProjectReference")
            Console.WriteLine($"    -> references: {i.Text}");
        if (i.Name == "PackageReference")
            Console.WriteLine($"    -> package: {i.Text}");
    });
});

// Show source file contents if embedded
Console.WriteLine("\n=== SOURCE FILES REFERENCED IN ERRORS ===");
build.VisitAllChildren<Error>(e => {
    Console.WriteLine($"\n  File: {e.File}");
    Console.WriteLine($"  Line: {e.LineNumber}, Col: {e.ColumnNumber}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Message: {e.Text}");
});

// Look for package restore info
Console.WriteLine("\n=== PACKAGE RESTORE INFO ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("PackageReference") || m.Text.Contains("restore")))
        Console.WriteLine($"  {m.Text}");
});
