    if (m.Text != null && (
        m.Text.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) ||
        m.Text.Contains("PackageReference", StringComparison.OrdinalIgnoreCase) ||
        m.Text.Contains("package", StringComparison.OrdinalIgnoreCase) ||
        m.Text.Contains("restore", StringComparison.OrdinalIgnoreCase) ||
        m.Text.Contains("NU", StringComparison.OrdinalIgnoreCase)
        )) {
        var text = m.Text.Length > 300 ? m.Text.Substring(0,300) : m.Text;
        if (!text.Contains("NuGetSdkResolver") && !text.Contains("NuGetVersion") && !text.Contains("NuspecFile") && !text.Contains("_Nu"))
            Console.WriteLine($"  {text}");
    }
});

// Dump properties for Services project
Console.WriteLine("\n=== SERVICES.CSPROJ PROPERTIES ===");
build.VisitAllChildren<Property>(prop => {
    var node = prop.Parent;
    bool inServices = false;
    while (node != null) {
        if (node is Project p && p.Name.Contains("Services")) { inServices = true; break; }
        node = node.Parent;
    }
    if (inServices && (prop.Name.Contains("Package") || prop.Name.Contains("Reference")))
        Console.WriteLine($"  {prop.Name} = {prop.Value?.Substring(0, Math.Min(prop.Value.Length, 200))}");
});

// Look for the csproj file content that was evaluated
Console.WriteLine("\n=== IMPORTS/EVALUATED ITEMS ===");
build.VisitAllChildren<Import>(imp => {
    if (imp.Name != null && imp.Name.Contains("Services"))
        Console.WriteLine($"  Import: {imp.Name} -> {imp.ProjectFilePath}");
});
