using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

// Look for all messages related to NuGet/restore/packages
Console.WriteLine("=== NUGET/RESTORE MESSAGES ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null && (
        m.Text.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) ||
        m.Text.Contains("PackageReference", StringComparison.OrdinalIgnoreCase) ||
        m.Text.Contains("Restored", StringComparison.OrdinalIgnoreCase)
        )) {
        var text = m.Text.Length > 300 ? m.Text.Substring(0,300) : m.Text;
        Console.WriteLine($"  {text}");
    }
});

// Dump the tree structure for Services project to find package refs
Console.WriteLine("\n=== SERVICES PROJECT TREE (first 3 levels) ===");
build.VisitAllChildren<Project>(p => {
    if (p.Name == "Services.csproj") {
        PrintTree(p, 0, 3);
    }
});

static void PrintTree(BaseNode node, int depth, int maxDepth) {
    if (depth >= maxDepth) return;
    var indent = new string(' ', depth * 2);
    var text = node.ToString();
    if (text != null && text.Length > 150) text = text.Substring(0, 150);
    Console.WriteLine($"{indent}{node.GetType().Name}: {text}");
    if (node is TreeNode tn) {
        foreach (var child in tn.Children) {
            if (child is BaseNode bn)
                PrintTree(bn, depth + 1, maxDepth);
        }
    }
