using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

// Get actual PackageReference items from the project file evaluation
Console.WriteLine("=== ALL AddItem ENTRIES ===");
build.VisitAllChildren<AddItem>(ai => {
    var proj = "";
    var node = ai.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    if (proj.Contains("Services") && !ai.Name.StartsWith("_")) {
        foreach (var child in ai.Children) {
            if (child is Item item)
                Console.WriteLine($"  [{ai.Name}] {item.Text}");
        }
    }
});

// Get Properties from Services project evaluation
Console.WriteLine("\n=== SERVICES PROPERTIES (Package-related) ===");
build.VisitAllChildren<Property>(prop => {
    var node = prop.Parent;
    bool inServices = false;
    while (node != null) {
        if (node is Project p && p.Name.Contains("Services")) { inServices = true; break; }
        node = node.Parent;
    }
    if (inServices && prop.Name.Contains("Package", StringComparison.OrdinalIgnoreCase))
        Console.WriteLine($"  {prop.Name} = {prop.Value}");
});

// Check the project.assets.json or other restore output
Console.WriteLine("\n=== RESTORE GRAPH INFO ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null) {
        var proj = "";
        var node = m.Parent;
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = node.Parent;
        }
        if (proj.Contains("Services") && m.Text.Contains("PackageReference"))
            Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 300))}");
    }
});

// Show the project dependency structure
Console.WriteLine("\n=== PROJECT DEPENDENCY GRAPH ===");
var projectDeps = new Dictionary<string, List<string>>();
build.VisitAllChildren<AddItem>(ai => {
    if (ai.Name == "ProjectReference") {
        var proj = "";
        var node = ai.Parent;
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = node.Parent;
        }
        if (!projectDeps.ContainsKey(proj)) projectDeps[proj] = new List<string>();
        foreach (var child in ai.Children) {
            if (child is Item item && !projectDeps[proj].Contains(item.Text))
                projectDeps[proj].Add(item.Text);
        }
    }
});
foreach (var kv in projectDeps)
    Console.WriteLine($"  {kv.Key} -> {string.Join(", ", kv.Value)}");
