Console.WriteLine("=== PROJECT DEPENDENCY GRAPH ===");
var seen = new HashSet<string>();
build.VisitAllChildren<AddItem>(ai => {
    if (ai.Name == "ProjectReference") {
        var proj = "";
        var node = ai.Parent;
        while (node != null) {
            if (node is Project p) { proj = p.Name; break; }
            node = node.Parent;
        }
        foreach (var child in ai.Children) {
            if (child is Item item) {
                var key = $"{proj} -> {item.Text}";
                if (seen.Add(key))
                    Console.WriteLine($"  {key}");
            }
        }
    }
});

// Check if Api.csproj had errors
Console.WriteLine("\n=== ALL ERRORS WITH PROJECT CONTEXT ===");
build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    Console.WriteLine($"  [{proj}] {e.Code}: {e.Text} (at {e.File}:{e.LineNumber})");
});

// Check the source file content from the binlog
Console.WriteLine("\n=== CSPROJ FILE CONTENT (from evaluation) ===");
build.VisitAllChildren<TextFragment>(tf => {
    Console.WriteLine($"TextFragment: {tf.Text?.Substring(0, Math.Min(tf.Text?.Length ?? 0, 200))}");
});
